下面是一个分块函数和针对它的属性测试：

```js
export function chunk(items, size) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    out.push(items.slice(i, i + size));
  }
  return out;
}
```

```js
// 属性测试：size 由生成器随机产生，范围为 0..10
property('chunk 不丢元素', () => {
  const items = fc.array(fc.integer());
  const size = fc.integer({ min: 0, max: 10 });
  fc.assert(fc.property(items, size, (list, n) => {
    return chunk(list, n).flat().length === list.length;
  }));
});
```

